use std::sync::Mutex;

struct Inner {
    shut_down: bool,
    pending_release: Vec<u64>,
}

/// Tracks registered handles and releases them when they are dropped or at shutdown.
pub struct Registry {
    inner: Mutex<Inner>,
}

impl Registry {
    /// Creates an empty registry.
    pub fn new() -> Self {
        Registry {
            inner: Mutex::new(Inner { shut_down: false, pending_release: Vec::new() }),
        }
    }

    /// Marks the registry shut down and releases every queued handle.
    pub fn shutdown(&self) {
        let mut inner = self.inner.lock().unwrap();
        inner.shut_down = true;
        for id in inner.pending_release.drain(..) {
            release(id);
        }
    }

    /// Deregisters a handle; it is released at the next shutdown, or at once after one.
    pub fn deregister(&self, id: u64) {
        let mut inner = self.inner.lock().unwrap();
        if inner.shut_down {
            release(id);
            return;
        }
        inner.pending_release.push(id);
    }
}

fn release(id: u64) {
    println!("released {id}");
}

